mapper.select:
SELECT COALESCE(SUM(o.total_amount), 0) as totalSales, COUNT(DISTINCT o.order_id) as orderCount, COUNT(DISTINCT o.order_id ) + SUM(dine.number_of_guests) as customerCount, CASE WHEN COUNT(DISTINCT o.order_id) > 0 THEN ROUND(SUM(o.total_amount) / COUNT(DISTINCT o.order_id), 2) ELSE 0 END as avgOrderAmount FROM orders o JOIN dine_in_orders dine on dine.order_id = o.order_id WHERE o.status IN ('2005005', '2004005')
AND DATE(o.create_time) >= #{query.startDate}
AND DATE(o.create_time) <= #{query.endDate}

SELECT d.dish_id as dishId, d.dish_name as dishName, SUM(od.number) as quantity, SUM(od.number * d.price) as amount FROM dining_hall.dish d JOIN dining_hall.order_detail od ON d.dish_id = od.dish_id JOIN dining_hall.orders o ON od.order_id = o.order_id WHERE o.status IN ('2005005', '2004005')
AND DATE(o.create_time) >= #{query.startDate}
AND DATE(o.create_time) <= #{query.endDate}
AND d.category = #{query.categoryId}
GROUP BY d.dish_id, d.dish_name ORDER BY amount DESC LIMIT 10

SELECT
    status as status,
    COUNT(*) as count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM dining_hall.orders 
        WHERE status IN ('2005005', '2004005','2004004','2005006','2005002','2005004','2004002','2004003')

            AND DATE(create_time) >= #{query.startDate}


            AND DATE(create_time) <= #{query.endDate}

    ), 2) as percentage
FROM orders
WHERE status IN ('2005005', '2004005','2004004','2005006','2005002','2005004','2004002','2004003')

    AND DATE(create_time) >= #{query.startDate}


    AND DATE(create_time) <= #{query.endDate}

GROUP BY status

SELECT COUNT(DISTINCT o.order_id)
FROM orders o
WHERE 1=1

    AND DATE(o.create_time) >= #{query.startDate}


    AND DATE(o.create_time) <=#{query.endDate}

SELECT d.dish_id as dishId, d.dish_name as dishName, SUM(od.number) as quantity, SUM(od.number * d.price) as amount, SUM(od.number * d.price * 0.4) as cost, SUM(od.number * d.price * 0.6) as profit, 60.0 as profitMargin, 0 as rank FROM dish d JOIN order_detail od ON d.dish_id = od.dish_id JOIN orders o ON od.order_id = o.order_id WHERE o.status IN ('2005005', '20040005')
AND DATE(o.create_time) >= #{query.startDate}
AND DATE(o.create_time) <=#{query.endDate}
AND d.category = #{query.categoryId}
GROUP BY d.dish_id, d.dish_name ORDER BY profit DESC LIMIT 10
